    /// Which effect's knob is under `pos`, if any.
    /// Which knob is under `pos`, if any. See [`recorder_panel::Hit::is_knob`].
    fn knob_under(&self, band: Option<Rect>, pos: Pos2) -> Option<recorder_panel::Hit> {
        let r = band.filter(|r| r.contains(pos))?;
        let view = self.recorder_layout_view();
        let h = recorder_panel::hit_test(r, &view, pos).filter(|h| h.is_knob())?;
        // The DIAL itself, not its cell: the cell is mostly margin, and a
        // right-click two ticks into the paint was eaten as the knob's.
        let cell = recorder_panel::knob_rect(r, &view, h)?;
        let vari = matches!(h, recorder_panel::Hit::SetVarispeed(_));
        // The word's room, which is what decides how much of the pitch dial's
        // cell the dial itself gets — see `recorder_panel::vari_face`.
        let word = recorder_panel::vari_word_rect(r, &view);
        recorder_panel::on_knob_circle(cell, word, pos, vari).then_some(h)
    }

    /// Whether `pos` is on a fader — its track, its icon or its number.
    fn fader_under(&self, band: Option<Rect>, pos: Pos2) -> bool {
        let Some(r) = band.filter(|r| r.contains(pos)) else {
            return false;
        };
        let view = self.recorder_layout_view();
        matches!(
            recorder_panel::hit_test(r, &view, pos),
            Some(recorder_panel::Hit::Type(_))
        )
    }

    fn fx_under(&self, band: Option<Rect>, pos: Pos2) -> Option<recorder_panel::Fx> {
        let band = band.filter(|r| r.contains(pos))?;
        let view = self.recorder_layout_view();
        recorder_panel::Fx::ALL.into_iter().find(|fx| {
            recorder_panel::knob_rect(band, &view, fx.hit())
                .is_some_and(|cell| {
                    recorder_panel::on_knob_circle(cell, Rect::NOTHING, pos, false)
                })
        })
    }

    /// Where the open effect panel hangs from: its own knob.
    fn fx_anchor(&self, fx: recorder_panel::Fx) -> Rect {
        let view = self.recorder_layout_view();
        recorder_panel::knob_rect(self.last_band, &view, fx.hit()).unwrap_or(Rect::NOTHING)
    }

    /// A press or a drag inside the open effect panel.
    ///
    /// **A drag stays on the row it started on.** Once `fx_drag` names a key,
    /// every later position sets THAT key, wherever the pointer has slid to —
    /// the same rule the band's own faders follow, and for the same reason: a
    /// hand that drifts up a row must not start setting the row above.
    /// The anchor the range panel hangs off: the dial that opened it.
    fn vari_anchor(&self) -> Rect {
        let view = self.recorder_layout_view();
        recorder_panel::knob_rect(
            self.last_band,
            &view,
            recorder_panel::Hit::SetVarispeed(0.5),
        )
        .unwrap_or(Rect::NOTHING)
    }

    /// A press inside the open varispeed range panel.
    fn press_in_vari_panel(&mut self, screen: Rect, pos: Pos2) {
        let anchor = self.vari_anchor();
        match recorder_panel::vari_hit_test(screen, anchor, pos) {
            Some(recorder_panel::VariHit::Type(field)) => {
                self.apply_recorder_hit(recorder_panel::Hit::Type(field));
            }
            Some(recorder_panel::VariHit::Reset) => {
                // **The RANGE, and not the dial.** Somebody who has widened
                // the reach and wants it back has not asked for the speed to
                // change, and `set_min`/`set_max` keep it — see their notes.
                self.settings.varispeed.set_min(crate::varispeed::DEFAULT_MIN);
                self.settings.varispeed.set_max(crate::varispeed::DEFAULT_MAX);
                self.num_edit = None;
                self.save_settings();
            }
            Some(recorder_panel::VariHit::Close) => {
                self.vari_open = false;
                self.num_edit = None;
            }
            // Panel chrome swallows the press; outside it, the press closes
            // the panel and is SPENT — the rule `press_in_fx_panel` gives.
            None => {
                if !recorder_panel::vari_popup_rect(screen, anchor).contains(pos) {
                    self.vari_open = false;
                    self.num_edit = None;
                    self.menu_ate_press = true;
                }
            }
        }
    }

    fn press_in_fx_panel(
        &mut self,
        screen: Rect,
        fx: recorder_panel::Fx,
        pos: Pos2,
        pressed: bool,
    ) {
        let anchor = self.fx_anchor(fx);
        if let Some(key) = self.fx_drag {
            if let Some(v) = recorder_panel::fx_value_at(screen, anchor, fx, key, pos) {
                self.set_effect_param(key, v);
            }
            return;
        }
        if !pressed {
            return;
        }
        let open = self
            .fx_choice
            .map(|k| (k, self.choice_list(k).0.len()));
        match recorder_panel::fx_hit_test(screen, anchor, fx, pos, open, self.delay_is_free()) {
            Some(recorder_panel::FxHit::Set { key, value }) => {
                self.fx_drag = Some(key);
                self.set_effect_param(key, value);
            }
            Some(recorder_panel::FxHit::OpenChoice { key }) => {
                // A second press on the same row puts it away, which is what
                // every menu in the app does and what a hand expects.
                self.fx_choice = (self.fx_choice != Some(key)).then_some(key);
            }
            Some(recorder_panel::FxHit::PickChoice { key, index }) => {
                self.pick_choice(key, index);
                self.fx_choice = None;
            }
            Some(recorder_panel::FxHit::CloseChoice) => self.fx_choice = None,
            Some(recorder_panel::FxHit::Reset(fx)) => self.reset_effect(fx),
            Some(recorder_panel::FxHit::Close) => {
                self.fx_open = None;
                self.fx_choice = None;
            }
            // A press on the panel's own chrome is swallowed; one outside it
            // closes the panel and does nothing else — SPENT, so the
            // surfaces that read `band_popup_owns` later this frame do not
            // catch the dismissal as a fresh press of their own.
            None => {
                if !recorder_panel::fx_popup_rect(screen, anchor).contains(pos) {
                    self.fx_open = None;
                    self.menu_ate_press = true;
                }
            }
        }
    }

    /// Write one effect parameter, 0..=1.
    fn set_effect_param(&mut self, key: &str, value: f32) {
        let v = f64::from(value.clamp(0.0, 1.0));
        self.settings
            .effect_params
            .insert(key.to_owned(), serde_json::Value::from(v));
        self.save_settings_soon();
    }

